	/**
	 * Internal helper method to load the root 
	 * 
	 * @param		id	UUID
	 * @return		DataSet
	 */
	protected DataSet load( UUID id ) throws ProcessingException {
		dataSet = DataSetService.getDataSetInstance().getDataSet( new DataSetFetchOneSummary(id) );	
		return dataSet;
	}


